// Worker entry point (wrangler.jsonc `main`). Wraps the worker OpenNext
// generates so resized images are kept in Cloudflare's edge cache; see
// lib/images/edgeImageCache.ts. Everything else goes straight to OpenNext.
//
// This file is bundled by wrangler, not checked by `tsc` (it's excluded in
// tsconfig.json): it imports `.open-next/worker.js`, which only exists after
// `opennextjs-cloudflare build`. The logic lives in lib/, which is checked
// and tested.

import { withEdgeImageCache, type EdgeCache, type WaitUntil } from "./lib/images/edgeImageCache";
// @ts-ignore -- generated by `opennextjs-cloudflare build`
import openNextWorker from "./.open-next/worker.js";

// OpenNext's worker also exports these Durable Object classes; re-export
// them so the entry point stays a drop-in replacement for it.
// @ts-ignore -- generated by `opennextjs-cloudflare build`
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js";

type OpenNextWorker = {
  fetch(request: Request, env: unknown, ctx: WaitUntil): Promise<Response>;
};

const worker = {
  async fetch(request: Request, env: unknown, ctx: WaitUntil): Promise<Response> {
    const openNext = openNextWorker as OpenNextWorker;
    const edgeCache = (caches as unknown as { default: EdgeCache }).default;
    return withEdgeImageCache(request, ctx, edgeCache, () => openNext.fetch(request, env, ctx));
  },
};

export default worker;
